CREATE OR REPLACE FUNCTION trg_relation_row_insert() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF (SELECT syncing FROM relation_sync_control WHERE id=1)=0 AND EXISTS(SELECT 1 FROM relation_endpoints WHERE page_id=NEW.page_id) THEN
    INSERT INTO relation_changes VALUES(NEW.id,NEW.page_id,NULL,NEW.cells,NULL) ON CONFLICT(row_id) DO UPDATE SET new_cells=NEW.cells;
  END IF;
  RETURN NULL;
END
$fn$;
CREATE OR REPLACE TRIGGER relation_row_insert AFTER INSERT ON rows FOR EACH ROW EXECUTE FUNCTION trg_relation_row_insert();

CREATE OR REPLACE FUNCTION trg_relation_row_update() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF OLD.cells!=NEW.cells AND (SELECT syncing FROM relation_sync_control WHERE id=1)=0 AND EXISTS(SELECT 1 FROM relation_endpoints WHERE page_id=NEW.page_id) THEN
    INSERT INTO relation_changes VALUES(NEW.id,NEW.page_id,OLD.cells,NEW.cells,OLD.version) ON CONFLICT(row_id) DO UPDATE SET new_cells=NEW.cells;
  END IF;
  RETURN NULL;
END
$fn$;
CREATE OR REPLACE TRIGGER relation_row_update AFTER UPDATE OF cells ON rows FOR EACH ROW EXECUTE FUNCTION trg_relation_row_update();

CREATE OR REPLACE FUNCTION trg_relation_row_delete() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF (SELECT syncing FROM relation_sync_control WHERE id=1)=0 AND EXISTS(SELECT 1 FROM relation_endpoints WHERE page_id=OLD.page_id) THEN
    INSERT INTO relation_changes VALUES(OLD.id,OLD.page_id,OLD.cells,NULL,OLD.version) ON CONFLICT(row_id) DO UPDATE SET new_cells=NULL;
  END IF;
  RETURN NULL;
END
$fn$;
CREATE OR REPLACE TRIGGER relation_row_delete AFTER DELETE ON rows FOR EACH ROW EXECUTE FUNCTION trg_relation_row_delete();

