CREATE OR REPLACE FUNCTION trg_rows_number_counter() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF NEW.number IS NULL THEN
    INSERT INTO row_counters(page_id,last) VALUES(NEW.page_id,(SELECT COALESCE(MAX(number),0) FROM rows WHERE page_id=NEW.page_id)) ON CONFLICT(page_id) DO NOTHING;
    UPDATE row_counters SET last=last+1 WHERE page_id=NEW.page_id;
    UPDATE rows SET number=(SELECT last FROM row_counters WHERE page_id=NEW.page_id) WHERE id=NEW.id;
  END IF;
  RETURN NULL;
END
$fn$;
CREATE OR REPLACE TRIGGER rows_number_counter AFTER INSERT ON rows FOR EACH ROW EXECUTE FUNCTION trg_rows_number_counter();

CREATE OR REPLACE FUNCTION trg_notification_inbox_pref() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF NOT (COALESCE((SELECT np.inbox FROM notification_prefs np WHERE np.user_id=NEW.user_id AND np.kind=NEW.kind),(SELECT nd.inbox FROM notification_defaults nd WHERE nd.kind=NEW.kind),1)=1) THEN
    RETURN NULL;
  END IF;
  RETURN NEW;
END
$fn$;
CREATE OR REPLACE TRIGGER notification_inbox_pref BEFORE INSERT ON notifications FOR EACH ROW EXECUTE FUNCTION trg_notification_inbox_pref();

CREATE OR REPLACE FUNCTION trg_queue_notification_push() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  INSERT INTO push_deliveries(notification_id,subscription_id) SELECT NEW.id,s.id FROM push_subscriptions s JOIN sessions se ON se.token=s.session_token WHERE s.user_id=NEW.user_id AND se.expires>(floor(extract(epoch from statement_timestamp()))*1000)::bigint
    AND COALESCE((SELECT np.push FROM notification_prefs np WHERE np.user_id=NEW.user_id AND np.kind=NEW.kind),(SELECT nd.push FROM notification_defaults nd WHERE nd.kind=NEW.kind),1)=1;
  RETURN NULL;
END
$fn$;
CREATE OR REPLACE TRIGGER queue_notification_push AFTER INSERT ON notifications FOR EACH ROW EXECUTE FUNCTION trg_queue_notification_push();

