CREATE OR REPLACE FUNCTION trg_grants_resource_kind() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  IF NEW.resource_kind IS NULL THEN
    UPDATE grants SET resource_kind=CASE WHEN EXISTS(SELECT 1 FROM pages WHERE id=NEW.resource_id) THEN 'page' ELSE 'space' END,workspace_id=COALESCE((SELECT workspace_id FROM pages WHERE id=NEW.resource_id),(SELECT workspace_id FROM spaces WHERE id=NEW.resource_id)) WHERE resource_id IS NOT DISTINCT FROM NEW.resource_id AND user_id IS NOT DISTINCT FROM NEW.user_id AND group_id IS NOT DISTINCT FROM NEW.group_id AND resource_kind IS NULL AND EXISTS(SELECT 1 FROM pages WHERE id=NEW.resource_id)!=EXISTS(SELECT 1 FROM spaces WHERE id=NEW.resource_id);
  END IF;
  RETURN NULL;
END
